import{_ as t,o as a,c as s,l as i,t as o,N as r}from"./chunks/framework.Gjrf2Eoj.js";const m=JSON.parse('{"title":"git-show-ref | x-cmd man (git man1) | List references in a local repository","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-show-ref - List references in a local repository","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-show-ref | x-cmd man (git man1) | List references in a local repository"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-show-ref - List references in a local repository"}]]},"headers":[],"params":{"isMan":true,"man":"git-show-ref","category":"git man1","desc":"List references in a local repository"},"relativePath":"git/man1/git-show-ref.md","filePath":"git/man1/git-show-ref.md"}'),n={name:"git/man1/git-show-ref.md"},h={class:"visually-hidden"},l=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-show-ref - List references in a local repository</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show-ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-q </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --quiet]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--verify] [--head] [-d </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --dereference]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-s </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --hash[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] [--abbrev[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] [--tags]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--heads] [--] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pattern</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show-ref</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --exclude-existing[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pattern</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Displays references available in a local repository along with the associated commit IDs. Results can be filtered using a pattern and tags can be dereferenced into object IDs. Additionally, it can be used to test whether a particular ref exists.</p><p>By default, shows the tags, heads, and remote refs.</p><p>The --exclude-existing form is a filter that does the inverse. It reads refs from stdin, one ref per line, and shows those that don&#39;t exist in the local repository.</p><p>Use of this utility is encouraged in favor of directly accessing files under the <strong>.git</strong> directory.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--head</p><blockquote><p>Show the HEAD reference, even if it would normally be filtered out.</p></blockquote><p>--heads, --tags</p><blockquote><p>Limit to &quot;refs/heads&quot; and &quot;refs/tags&quot;, respectively. These options are not mutually exclusive; when given both, references stored in &quot;refs/heads&quot; and &quot;refs/tags&quot; are displayed.</p></blockquote><p>-d, --dereference</p><blockquote><p>Dereference tags into object IDs as well. They will be shown with &quot;^{}&quot; appended.</p></blockquote><p>-s, --hash[=&lt;n&gt;]</p><blockquote><p>Only show the SHA-1 hash, not the reference name. When combined with --dereference the dereferenced tag will still be shown after the SHA-1.</p></blockquote><p>--verify</p><blockquote><p>Enable stricter reference checking by requiring an exact ref path. Aside from returning an error code of 1, it will also print an error message if <strong>--quiet</strong> was not specified.</p></blockquote><p>--abbrev[=&lt;n&gt;]</p><blockquote><p>Abbreviate the object name. When using <strong>--hash</strong>, you do not have to say <strong>--hash --abbrev</strong>; <strong>--hash=n</strong> would do.</p></blockquote><p>-q, --quiet</p><blockquote><p>Do not print any results to stdout. When combined with <strong>--verify</strong> this can be used to silently check if a reference exists.</p></blockquote><p>--exclude-existing[=&lt;pattern&gt;]</p><blockquote><p>Make <em>git show-ref</em> act as a filter that reads refs from stdin of the form &quot;<strong>^(?:&lt;anything&gt;\\s)?&lt;refname&gt;(?:\\^{})?$</strong>&quot; and performs the following actions on each: (1) strip &quot;^{}&quot; at the end of line if any; (2) ignore if pattern is provided and does not head-match refname; (3) warn if refname is not a well-formed refname and skip; (4) ignore if refname is a ref that exists in the local repository; (5) otherwise output the line.</p></blockquote><p>&lt;pattern&gt;...</p><blockquote><p>Show references matching one or more patterns. Patterns are matched from the end of the full name, and only complete parts are matched, e.g. <em>master</em> matches <em>refs/heads/master</em>, <em>refs/remotes/origin/master</em>, <em>refs/tags/jedi/master</em> but not <em>refs/heads/mymaster</em> or <em>refs/remotes/master/jedi</em>.</p></blockquote><h2 id="output" tabindex="-1">OUTPUT <a class="header-anchor" href="#output" aria-label="Permalink to &quot;OUTPUT&quot;">​</a></h2><p>The output is in the format: <em>&lt;SHA-1 ID&gt;</em> <em>&lt;space&gt;</em> <em>&lt;reference name&gt;</em>.</p><blockquote><pre><code>$ git show-ref --head --dereference
832e76a9899f560a90ffd62ae2ce83bbeff58f54 HEAD
832e76a9899f560a90ffd62ae2ce83bbeff58f54 refs/heads/master
832e76a9899f560a90ffd62ae2ce83bbeff58f54 refs/heads/origin
3521017556c5de4159da4615a39fa4d5d2c279b5 refs/tags/v0.99.9c
6ddc0964034342519a87fe013781abf31c6db6ad refs/tags/v0.99.9c^{}
055e4ae3ae6eb344cbabf2a5256a49ea66040131 refs/tags/v1.0rc4
423325a2d24638ddcc82ce47be5e40be550f4507 refs/tags/v1.0rc4^{}
...
</code></pre></blockquote><p>When using --hash (and not --dereference) the output format is: <em>&lt;SHA-1 ID&gt;</em></p><blockquote><pre><code>$ git show-ref --heads --hash
2e3ba0114a1f52b47df29743d6915d056be13278
185008ae97960c8d551adcd9e23565194651b5d1
03adf42c988195b50e1a1935ba5fcbc39b2b029b
...
</code></pre></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>To show all references called &quot;master&quot;, whether tags or heads or anything else, and regardless of how deep in the reference naming hierarchy they are, use:</p><blockquote><pre><code>        git show-ref master
</code></pre></blockquote><p>This will show &quot;refs/heads/master&quot; but also &quot;refs/remote/other-repo/master&quot;, if such references exists.</p><p>When using the <strong>--verify</strong> flag, the command requires an exact path:</p><blockquote><pre><code>        git show-ref --verify refs/heads/master
</code></pre></blockquote><p>will only match the exact branch called &quot;master&quot;.</p><p>If nothing matches, <em>git show-ref</em> will return an error code of 1, and in the case of verification, it will show an error message.</p><p>For scripting, you can ask it to be quiet with the &quot;--quiet&quot; flag, which allows you to do things like</p><blockquote><pre><code>        git show-ref --quiet --verify -- &quot;refs/heads/$headname&quot; ||
                echo &quot;$headname is not a valid branch&quot;
</code></pre></blockquote><p>to check whether a particular branch exists or not (notice how we don&#39;t actually want to show any results, and we want to use the full refname for it in order to not trigger the problem with ambiguous partial matches).</p><p>To show only tags, or only proper branch heads, use &quot;--tags&quot; and/or &quot;--heads&quot; respectively (using both means that it shows tags and heads, but not other random references under the refs/ subdirectory).</p><p>To do automatic tag object dereferencing, use the &quot;-d&quot; or &quot;--dereference&quot; flag, so you can do</p><blockquote><pre><code>        git show-ref --tags --dereference
</code></pre></blockquote><p>to get a listing of all tags together with what they dereference.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><p>*<em>.git/refs/*</em> *, <strong>.git/packed-refs</strong></p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-for-each-ref</strong>(1), <strong>git-ls-remote</strong>(1), <strong>git-update-ref</strong>(1), <strong>gitrepository-layout</strong>(5)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,54);function p(e,d,c,f,g,u){return a(),s("div",null,[i("h1",h,o(e.$params.man),1),l])}const b=t(n,[["render",p]]);export{m as __pageData,b as default};
